def evaluate_correct(
        self, questions: List[str], responses: List[str], expected_answers: List[str]
) -> Tuple[float, int, List[str]]:

    reasoning = []
    response = responses[0]
    correct_score = 0
    incorrect_set = self.get_answers_for_others(expected_answers)

    for potential_answers in expected_answers:
        found = False
        for pa in potential_answers:
            regex = re.compile(rf"\b{pa}\b")
            if len(regex.findall(response)) > 0:
                found = True
                break
        if not found:
            reasoning.append(f"{potential_answers} not found in answer.")
        else:
            reasoning.append("Answer contains expected keyword(s)")
            correct_score += 1

    # Check to see if the agent is confused
    confusion_score = 0
    for incorrect_term in incorrect_set:
        regex = re.compile(rf"\b{incorrect_term}\b")
        if len(regex.findall(response)) > 0:
            reasoning.append(f"Answer also contains `{incorrect_term}`, which indicates that the agent has recalled something incorrect.")
            confusion_score = 1

        # You only get marked down once for this
        if confusion_score == 1:
            break

    score = max((correct_score - confusion_score) / 3, 0.0)

    return score, 1, reasoning

def get_answers_for_others(self, expected_answers):
    other_answers = set()
    for tup in CODED_INFO_TIME + CODED_INFO_THING + CODED_INFO_PLACE:
        for item in tup[1]:
            other_answers.add(item)

    for expected_list in expected_answers:
        for e in expected_list:
            other_answers.discard(e)

    return other_answers

import string
from rouge_score import rouge_scorer


def rouge_l(reference: str, candidate: str) -> float:
    scorer = rouge_scorer.RougeScorer(["rougeL"], use_stemmer=True)
    return scorer.score(reference, candidate)["rougeL"].fmeasure


def standardise(text: str) -> str:
    table = str.maketrans("", "", string.punctuation)
    return text.lower().translate(table)

def evaluate_single(self, actual: str, expected: str) -> tuple[int, str]:
    actual_std = standardise(actual)
    expected_std = standardise(expected)
    if expected_std in actual_std or rouge_l(expected_std, actual_std) > self.rouge_score_threshold:
        return 1, f"'{expected}' is in the response."
    context = [make_user_message(eval_prompt.format(message=actual, sentence=expected))]
    eval_str = self.ask_llm(context, GPT_CHEAPEST)
    try:
        eval_json = sanitize_and_parse_json(eval_str)
        present = eval_json["present"]
        if present:
            present = rouge_l(expected_std, standardise(eval_json["sentence"])) > self.rouge_score_threshold
    except (ValueError, JSONDecodeError, KeyError) as exc:
        return 0, f"Could not evaluate due to a JSON parsing error: {repr(exc)}"
    not_str = "" if present else "not "
    return int(present), f"'{expected}' is {not_str}in the response."

def __post_init__(self):
    super().__post_init__()
    if self.max_prompt_size is None:
        self.max_prompt_size = get_max_prompt_size(self.model)
    else:
        lite_llm_max = get_max_prompt_size(self.model)
        if lite_llm_max > 0:
            self.max_prompt_size = min(self.max_prompt_size, lite_llm_max)

def reply(self, user_message: str, agent_response: Optional[str] = None) -> str:
    if self.verbose:
        print(f"USER: {user_message}")

    def cost_callback(cost_usd: float):
        self.costs_usd += cost_usd

    self.context.append(make_user_message(user_message))
    if agent_response is None:
        c_callback = None if self.is_local else cost_callback
        response = ask_llm(self.context, self.model, context_length=self.max_prompt_size, cost_callback=c_callback,
                           max_response_tokens=self.max_response_tokens)
    else:
        response = agent_response

    self.context.append(make_assistant_message(response))

    if self.verbose:
        print(f"AGENT: {response}")
    return response

def reset(self):
    self.context = [make_system_message(_system_prompt)]

def mean_std(values: list) -> tuple[float, float]:
    mean = sum(values) / len(values)
    var = sum([(mean - v) ** 2 for v in values]) / len(values)
    return mean, var ** 0.5

